"""Parquet data sampler with random, stratified, and systematic strategies."""

import argparse
import sys

import numpy as np
import pyarrow.parquet as pq


def random_sample(table, n=None, frac=None, seed=None):
    """Uniform random sampling of rows."""
    total = table.num_rows
    size = _resolve_size(total, n, frac)
    rng = np.random.default_rng(seed)
    indices = rng.choice(total, size=size, replace=False)
    return table.take(np.sort(indices))


def stratified_sample(table, stratum_col, n_per_stratum=None, frac=None, seed=None):
    """Sample proportionally (or fixed count) within each stratum."""
    col = table.column(stratum_col)
    categories = col.to_pylist()
    unique_vals, counts = np.unique(categories, return_counts=True)
    rng = np.random.default_rng(seed)

    indices = []
    for val, count in zip(unique_vals, counts):
        if n_per_stratum is not None:
            k = min(n_per_stratum, count)
        elif frac is not None:
            k = max(1, int(count * frac))
        else:
            raise ValueError("Specify n_per_stratum or frac")
        stratum_indices = np.where(np.array(categories) == val)[0]
        chosen = rng.choice(stratum_indices, size=k, replace=False)
        indices.extend(chosen)

    return table.take(np.sort(indices))


def systematic_sample(table, n=None, frac=None, start=None, seed=None):
    """Select every k-th row starting from a random (or given) offset."""
    total = table.num_rows
    size = _resolve_size(total, n, frac)
    k = max(1, total // size)
    rng = np.random.default_rng(seed)
    offset = start if start is not None else rng.integers(0, k)
    indices = np.arange(offset, total, k)[:size]
    return table.take(indices)


def _resolve_size(total, n, frac):
    if n is not None and frac is not None:
        raise ValueError("Specify n or frac, not both")
    if n is not None:
        return min(n, total)
    if frac is not None:
        return max(1, int(total * frac))
    raise ValueError("Specify n or frac")


def print_summary(table, label="Result"):
    """Print shape and first few rows of a sampled table."""
    df = table.to_pandas()
    print(f"\n=== {label} ({df.shape[0]} rows x {df.shape[1]} cols) ===")
    print(df.head(10).to_string(index=False))
    if df.shape[0] > 10:
        print(f"... ({df.shape[0] - 10} more rows)")


def main():
    parser = argparse.ArgumentParser(description="Sample Parquet files")
    parser.add_argument("input", help="Input Parquet file path")
    parser.add_argument("-o", "--output", help="Output Parquet file path")
    parser.add_argument(
        "-s",
        "--strategy",
        choices=["random", "stratified", "systematic"],
        default="random",
    )
    parser.add_argument("-n", "--num-rows", type=int, help="Exact number of rows to sample")
    parser.add_argument("-f", "--frac", type=float, help="Fraction of rows to sample (0-1)")
    parser.add_argument("--stratum-col", help="Column name for stratified sampling")
    parser.add_argument("--n-per-stratum", type=int, help="Rows per stratum (stratified only)")
    parser.add_argument("--start", type=int, help="Starting offset (systematic only)")
    parser.add_argument("--seed", type=int, help="Random seed")
    args = parser.parse_args()

    table = pq.read_table(args.input)

    if args.strategy == "random":
        result = random_sample(table, n=args.num_rows, frac=args.frac, seed=args.seed)
    elif args.strategy == "stratified":
        if not args.stratum_col:
            parser.error("--stratum-col is required for stratified sampling")
        result = stratified_sample(
            table,
            stratum_col=args.stratum_col,
            n_per_stratum=args.n_per_stratum,
            frac=args.frac,
            seed=args.seed,
        )
    elif args.strategy == "systematic":
        result = systematic_sample(
            table, n=args.num_rows, frac=args.frac, start=args.start, seed=args.seed
        )

    if args.output:
        pq.write_table(result, args.output)
        print(f"Wrote {result.num_rows} rows to {args.output}")
    else:
        print_summary(result, label=args.strategy)


if __name__ == "__main__":
    main()
